/*:
    A Zulip configuration that must be created before using the Zulip API.
 */
public class Config {
    //: An email address that is signed up for Zulip.
    public var emailAddress: String

    //: An API key for a Zulip user.
    public var apiKey: String

    /*:
        The URL of a Zulip realm.

        - Example: https://chat.zulip.org/api/v1
     */
    public var apiURL: String

    /*:
        Initializes a Zulip configuration.

         - Parameters:
            - emailAddress: An email address that is signed up for Zulip.
            - apiKey: An API key for a Zulip user.
            - realmURL: The URL of a Zulip realm.
              - Example: https://chat.zulip.org
     */
    public init(
        emailAddress: String,
        apiKey: String,
        realmURL: String
    ) {
        self.emailAddress = emailAddress
        self.apiKey = apiKey
        self.apiURL = realmURL + "/api/v1"
    }
}

import Alamofire

//: An error that occurs during a Zulip HTTP request.
public enum ZulipError: Error {
    //: An unexpected error that occurs without a message.
    case unknownError

    //: An error that is sent by Zulip, with an accompanying message.
    case error(message: String)
}

/*:
    Makes a `ZulipError` based on an Alamofire `DataResponse`.

     - Parameters:
        - response: An Alamofire `DataResponse` from a Zulip REST API request.
     - Returns: The `ZulipError`.
 */
internal func getZulipErrorFromResponse(
    response: DataResponse<Any>
) -> ZulipError {
    guard
        let errorMessage = getChildFromJSONResponse(
            response: response,
            childKey: "msg"
        ) as? String
    else {
        return ZulipError.unknownError
    }

    return ZulipError.error(message: errorMessage)
}

/*:
    A Zulip client. This is the primary way of interacting with Zulip through
    `swift-zulip-api`.
 */
public class Zulip {
    //: The Zulip `Config` that is used.
    public var config: Config

    /*:
        Initializes a Zulip client.

         - Parameters:
            - config: The `Config` to use.
     */
    public init(config: Config) {
        self.config = config
    }

    /*:
        Returns a `Messages` client with the current `Config`.

         - Returns: The `Messages` client.
     */
    public func messages() -> Messages {
        return Messages(config: self.config)
    }

    /*:
        Returns a `Streams` client with the current `Config`.

         - Returns: The `Streams` client.
     */
    public func streams() -> Streams {
        return Streams(config: self.config)
    }

    /*:
        Returns a `Users` client with the current `Config`.

         - Returns: The `Users` client.
     */
    public func users() -> Users {
        return Users(config: self.config)
    }

    /*:
        Returns an `Events` client with the current `Config`.

         - Returns: The `Events` client.
     */
    public func events() -> Events {
        return Events(config: self.config)
    }
}

import Foundation
import Alamofire

//: An error that occurs during events, before an HTTP request is made.
public enum EventError: Error {
    //: An error that occurs when a Zulip `narrow` is invalid.
    case invalidEventTypes

    //: An error that occurs when a Zulip `narrow` is invalid.
    case invalidFetchEventTypes

    //: An error that occurs when a Zulip `narrow` is invalid.
    case invalidNarrow
}

/*:
    A client for interacting with Zulip's event functionality.
 */
public class Events {
    private var config: Config

    /*:
        Initializes an Events client.

         - Parameters:
            - config: The `Config` to use.
     */
    public init(config: Config) {
        self.config = config
    }

    /*:
        Registers an event queue.

         - Parameters:
            - applyMarkdown: Whether event content should be rendered as
              Markdown to HTML.
            - clientGravatar: Whether Gravatars should not be sent if a user
              does not have an avatar. (`true` means that `avatar_url` will be
              `nil` if the user does not have an avatar; `false` means that an
              `avatar_url` will be a Gravatar).
            - eventTypes: The types of events to receive, or an empty array
              for all events.
               - Example: `["messages"]` for new messages
               - Example: `["subscriptions"]` for changes in the current user's
                 subscriptions
               - Example: `["realm_user"]` for changes in the users in the
                 current realm
               - Example: `["pointer"]` for changes in the current user's
                 pointer
               - Example: `["subscriptions", "pointer"]` for a combination of
                 multiple events
               - Example: `[]` for all events
            - allPublicStreams: Whether events should be received from all
              public streams.
            - includeSubscribers: Whether events should be received for the
              subscribers of each stream.
            - fetchEventTypes: The same as `eventTypes`, but used to fetch
              initial data. If `fetchEventTypes` is not set, `eventTypes` is
              used, and if neither are set, then no events are used.
            - narrow: A Zulip narrow to search for messages in. `narrow`
              should be an array of arrays consisting of filters.
               - Example: `[["stream", "test here"]]`
               - Example: `[
                     ["stream", "zulip-swift"],
                     ["sender", "theskunkmb@gmail.com"]
                 ]`
            - callback: A callback, which will be passed a dictionary
              containing `queue_id`, the ID of the new queue and
              `last_event_id`, the initial event ID to receive an event with,
              or an error if there is one.
     */
    public func register(
        applyMarkdown: Bool = false,
        clientGravatar: Bool = false,
