import Foundation
import Alamofire

/*:
    An error that occurs during stream operations, before an HTTP request is
    made.
 */
public enum StreamError: Error {
    //: An error that occurs when a list of Zulip streams is invalid.
    case invalidStreams

    //: An error that occurs when a list of Zulip principals is invalid.
    case invalidPrincipals

    //: An error that occurs when a list of Zulip stream names is invalid.
    case invalidStreamNames
}

//: A client for interacting with Zulip's messaging functionality.
public class Streams {
    private var config: Config

    /*:
        Initializes a `Streams` client.

         - Parameters:
            - config: The `Config` to use.
     */
    public init(config: Config) {
        self.config = config
    }

    /*:
        Gets all streams that a user can access.

         - Parameters:
            - includePublic: Whether all public streams should be included.
            - includeSubscribed: Whether all subscribed-to streams should be
              included
            - includeDefault: Whether all default streams should be included.
            - includeActive: Whether all active streams should be included.
              This option will cause a `ZulipError` if the user not an admin.
            - callback: A callback, which will be passed the streams, or an
              error.
     */
    public func getAll(
        includePublic: Bool = true,
        includeSubscribed: Bool = true,
        includeDefault: Bool = false,
        includeAllActive: Bool = false,
        callback: @escaping (
            [[String: Any]]?,
            Error?
        ) -> Void
    ) {
        let params = [
            "include_public": includePublic ? "true" : "false",
            "include_subscribed": includeSubscribed ? "true" : "false",
            "include_default": includeDefault ? "true" : "false",
            "include_all_active": includeAllActive ? "true" : "false",
        ]

        makeGetRequest(
            url: self.config.apiURL + "/streams",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let streams = getChildFromJSONResponse(
                        response: response,
                        childKey: "streams"
                    ) as? [[String: Any]]
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(streams, nil)
            }
        )
    }

    /*:
        Gets the ID of a stream.

         - Parameters:
            - name: The name of the stream.
            - callback: A callback, which will be passed the ID, or an error.
     */
    public func getID(
        name: String,
        callback: @escaping (Int?, Error?) -> Void
    ) {
        let params = [
            "stream": name,
        ]

        makeGetRequest(
            url: self.config.apiURL + "/get_stream_id",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let id = getChildFromJSONResponse(
                        response: response,
                        childKey: "stream_id"
                    ) as? Int
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(id, nil)
            }
        )
    }

    /*:
        Gets the user's subscribed streams.

         - Parameters:
            - callback: A callback, which will be passed the streams, or an
              error.
     */
    public func getSubscribed(
        callback: @escaping (
            [[String: Any]]?,
            Error?
        ) -> Void
    ) {
        makeGetRequest(
            url: self.config.apiURL + "/users/me/subscriptions",
            params: [:],
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let streams = getChildFromJSONResponse(
                        response: response,
                        childKey: "subscriptions"
                    ) as? [[String: Any]]
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(streams, nil)
            }
        )
    }

    /*:
        Subscribes a user to streams, or creates them if they do not exist yet.

         - Parameters:
            - streams: The streams to subscribe a user to.
               - Example: `[["name": "test here"]]`
               - Example: `["name": "test here"], ["name": "announce"]]`
            - inviteOnly: Whether the streams are invite only or not.
            - announce: Whether an announcement should be made that a new
              stream is created if it is.
            - principals: The users to subscribe to the streams. If
              `principals` is empty, the current user will be subscribed.
            - authorizationErrorsFatal: Whether authorization errors should be
              reported in the response.
            - callback: A callback, which will be passed a dictionary where the
              key is user's email, and the value is a list of streams they were
              subscribed to; a dictionary where the key is a user's email, and
              the value is a list of streams they are already subscribed to;
              and a list of names of streams that could not be subscribed to
              because the user was unauthorized; or an error if there is one.
     */
    public func subscribe(
        streams: [[String: Any]],
        inviteOnly: Bool = false,
        announce: Bool = false,
        principals: [String] = [],
        authorizationErrorsFatal: Bool = true,
        callback: @escaping (
            [String: [String]]?,
            [String: [String]]?,
            [String]?,
            Error?
        ) -> Void
    ) {
        guard
            let streamsData = try? JSONSerialization.data(
                withJSONObject: streams
            ),
            let streamsString = String(
                data: streamsData,
                encoding: String.Encoding.utf8
            )
        else {
            callback(nil, nil, nil, StreamError.invalidStreams)
            return
        }

        guard
            let principalsData = try? JSONSerialization.data(
                withJSONObject: principals
            ),
            let principalsString = String(
                data: principalsData,
                encoding: String.Encoding.utf8
            )
        else {
            callback(nil, nil, nil, StreamError.invalidPrincipals)
            return
        }

        let params = [
            "subscriptions": streamsString,
            "invite_only": inviteOnly ? "true" : "false",
            "announce": announce ? "true" : "false",
            "principals": principalsString,
            "authorization_errors_fatal":
                authorizationErrorsFatal ? "true" : "false",
        ]

        makePostRequest(
            url: self.config.apiURL + "/users/me/subscriptions",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                if let errorMessage = getChildFromJSONResponse(
                    response: response,
                    childKey: "msg"
                ) as? String, errorMessage != "" {
                    callback(
                        nil,
                        nil,
                        nil,
                        ZulipError.error(message: errorMessage)
                    )
                    return
                }

                let subscribed = getChildFromJSONResponse(
                    response: response,
                    childKey: "subscribed"
                ) as? [String: [String]]
                let alreadySubscribed = getChildFromJSONResponse(
                    response: response,
                    childKey: "already_subscribed"
                ) as? [String: [String]]
                let unauthorized = getChildFromJSONResponse(
                    response: response,
                    childKey: "unauthorized"
                ) as? [String]

                callback(subscribed, alreadySubscribed, unauthorized, nil)
            }
        )
    }

    /*:
        Unsubscribes a user to streams.

         - Parameters:
            - streamNames: The names of the streams to unsubscribe a user from.
               - Example: `["test here"]`
               - Example: `["test here", "announce"]`
            - principals: The users to unsubscribe from the streams. If
              `principals` is empty, the current user will be subscribed.
              Unsubscribing other users will cause a `ZulipError` if the
              current user is not an admin.
            - callback: A callback, which will be passed a list of names of
              the streams that were unsubscribed from and a list of names of
              the streams that could not be unsubscrived from because the user
              was already subscribed, or an error if there is one.
     */
    public func unsubscribe(
        streamNames: [String],
        principals: [String] = [],
        callback: @escaping (
            [String]?,
            [String]?,
            Error?
        ) -> Void
    ) {
        guard
            let streamNamesData = try? JSONSerialization.data(
                withJSONObject: streamNames
            ),
            let streamNamesString = String(
                data: streamNamesData,
                encoding: String.Encoding.utf8
            )
        else {
            callback(nil, nil, StreamError.invalidStreamNames)
            return
        }

        guard
            let principalsData = try? JSONSerialization.data(
                withJSONObject: principals
            ),
            let principalsString = String(
                data: principalsData,
                encoding: String.Encoding.utf8
            )
        else {
            callback(nil, nil, StreamError.invalidPrincipals)
            return
        }

        let params = [
            "subscriptions": streamNamesString,
            "principals": principalsString,
        ]

        makeDeleteRequest(
            url: self.config.apiURL + "/users/me/subscriptions",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                if let errorMessage = getChildFromJSONResponse(
                    response: response,
                    childKey: "msg"
                ) as? String, errorMessage != "" {
                    callback(
                        nil,
                        nil,
                        ZulipError.error(message: errorMessage)
                    )
                    return
                }

                let removed = getChildFromJSONResponse(
                    response: response,
                    childKey: "removed"
                ) as? [String]
                let notSubscribed = getChildFromJSONResponse(
                    response: response,
                    childKey: "not_subscribed"
                ) as? [String]

                callback(removed, notSubscribed, nil)
            }
        )
    }
}

import Foundation
import Alamofire

//: A type of Zulip message.
public enum MessageType: String {
    //: A stream message.
    case streamMessage = "stream"

    //: A private message.
    case privateMessage = "private"
}

//: An error that occurs during messaging, before an HTTP request is made.
public enum MessageError: Error {
    //: An error that occurs when a Zulip `narrow` is invalid.
    case invalidNarrow
}

/*:
    A client for interacting with Zulip's messaging functionality.
 */
public class Messages {
    private var config: Config

    /*:
        Initializes a Messaging client.

         - Parameters:
            - config: The `Config` to use.
     */
    public init(config: Config) {
        self.config = config
    }

    /*:
        Sends a message.

         - Parameters:
            - messageType: The type of message to send.
            - to: If `messageType` is `MessageType.stream`, then a string
              identifying a stream. If `messageType` is `MessageType.private`,
              then list of users' email addresses to send messages to.
               - Example: `StreamName`
               - Example: `user@example.com`
               - Example: `user1@example.com,user2@example.org`
            - subject: The subject of the message.
            - content: The content of the message, which will be formatted by
              Zulip's Markdown engine on the backend.
            - callback: A callback, which will be passed the ID of the new
              message, or an error.
     */
    public func send(
        messageType: MessageType,
        to: String,
        subject: String?,
        content: String,
        callback: @escaping (Int?, Error?) -> Void
    ) {
        var params = [
            "type": messageType.rawValue,
            "to": to,
            "content": content,
        ]

        if messageType == MessageType.streamMessage, let subject = subject {
            params["subject"] = subject
        }

        makePostRequest(
            url: self.config.apiURL + "/messages",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let id = getChildFromJSONResponse(
                        response: response,
                        childKey: "id"
                    ) as? Int
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(id, nil)
            }
        )
    }

    /*:
        Gets messages.

         - Parameters:
            - narrow: A Zulip narrow to search for messages in. `narrow`
              should be an array of arrays consisting of filters.
               - Example: `[["is", "private"]]`
               - Example: `[["stream", "zulip-swift"]]`
               - Example: `[
                      ["stream", "zulip-swift"],
                      ["sender", "theskunkmb@gmail.com"]
                  ]`
            - anchor: The ID of a message to start with. `anchor` can also be
              an extremely large number in order to retrieve the newest
              message.
               - Example: 130
               - Example: 1000000000
            - amountBefore: The amount of messages before the `anchor` message
              to include.
            - amountAfter: The amount of messages after the `anchor` message
              to include.
            - callback: A callback, which will be passed the messages, or an
              error.
     */
    public func get(
        narrow: [Any],
        anchor: Int,
        amountBefore: Int,
        amountAfter: Int,
        callback: @escaping (
            [[String: Any]]?,
            Error?
        ) -> Void
    ) {
        guard
            let narrowData = try? JSONSerialization.data(
                withJSONObject: narrow
            ),
            let narrowString = String(
                data: narrowData,
                encoding: String.Encoding.utf8
            )
        else {
            callback(nil, MessageError.invalidNarrow)
            return
        }

        let params = [
            "narrow": narrowString,
            "anchor": String(anchor),
            "num_before": String(amountBefore),
            "num_after": String(amountAfter)
        ]

        makeGetRequest(
            url: self.config.apiURL + "/messages",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let messages = getChildFromJSONResponse(
                        response: response,
                        childKey: "messages"
                    ) as? [[String: Any]]
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(messages, nil)
            }
        )
    }

    /*:
        Renders a message.

         - Parameters:
            - content: The content of the message, which will be formatted by
              Zulip's Markdown engine on the backend.
            - callback: A callback, which will be passed the rendered HTML
              string, or an `Error`.
     */
    public func render(
        content: String,
        callback: @escaping (String?, Error?) -> Void
    ) {
        let params = [
            "content": content,
        ]

        makePostRequest(
            url: self.config.apiURL + "/messages/render",
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let rendered = getChildFromJSONResponse(
                        response: response,
                        childKey: "rendered"
                    ) as? String
                else {
                    callback(
                        nil,
                        getZulipErrorFromResponse(response: response)
                    )
                    return
                }

                callback(rendered, nil)
            }
        )
    }

    /*:
        Updates a message.

         - Parameters:
            - content: The content of the message, which will be formatted by
              Zulip's Markdown engine on the backend.
            - callback: A callback, which will be passed an Error if
              there is one.
     */
    public func update(
        messageID: Int,
        content: String,
        callback: @escaping (Error?) -> Void
    ) {
        let params = [
            "content": content,
        ]

        makePatchRequest(
            url: self.config.apiURL + "/messages/" + String(messageID),
            params: params,
            username: config.emailAddress,
            password: [REDACTED],
            callback: { (response) in
                guard
                    let errorMessage = getChildFromJSONResponse(
                        response: response,
                        childKey: "msg"
                    ) as? String
                else {
                    callback(nil)
                    return
                }

                if (errorMessage == "") {
                    callback(nil)
                    return
                }

                callback(ZulipError.error(message: errorMessage))
            }
        )
    }
}

